/**
 * Returns a routes config from entries built by the `route()`.
 *
 * The returned config should be passed to `NavigationProvider`
 * and used when declaring the RouteRegister interface so TypeScript
 * can validate route names and parameters across your entire app.
 *
 * @see https://docs.stripe.com/stripe-apps/routing
 */
export function createRoutes(routes) {
    return routes;
}
